// Static exports preserve factual labels, never keyboard controls or hover state.
function cloneChartForExport(svg){
 const clone=svg.cloneNode(true),originals=[svg,...svg.querySelectorAll('*')],copies=[clone,...clone.querySelectorAll('*')];
 originals.forEach((node,i)=>{const copy=copies[i],style=getComputedStyle(node);for(const key of ['fill','stroke','stroke-width','stroke-dasharray','font-size','font-family','font-weight','opacity'])copy.style.setProperty(key,style.getPropertyValue(key));copy.style.animation='none';copy.style.transition='none';if(i===0||node.classList.contains('overlay-series')||node.classList.contains('annual-line'))copy.style.opacity='1';for(const key of ['tabindex','aria-description','aria-roledescription','aria-live','aria-describedby'])copy.removeAttribute(key)});
 clone.setAttribute('role','img');clone.setAttribute('focusable','false');clone.querySelectorAll('g[pointer-events="none"]:not(.finance-time-grid):not(.finance-endpoints)').forEach(n=>n.remove());return clone;
}
// Reflow narrow price-chart geometry for a consistent landscape download.
function normalizeExportPriceChart(svg){
 if(!svg.classList.contains('price-history-chart')&&!svg.classList.contains('annual-chart'))return;
 const vb=svg.viewBox.baseVal,grid=[...svg.querySelectorAll('.chart-gridline')];if(!grid.length)return;
 const left=Number(grid[0].getAttribute('x1')),right=Number(grid[0].getAttribute('x2')),top=Math.min(...grid.map(n=>Number(n.getAttribute('y1')))),bottom=Math.max(...grid.map(n=>Number(n.getAttribute('y1'))));
 if(!(right>left&&bottom>top))return;
 const x=v=>88+(v-left)/(right-left)*(1152-88-18),y=v=>28+(v-top)/(bottom-top)*(345-28);
 svg.querySelectorAll('line').forEach(n=>{for(const key of ['x1','x2'])if(n.hasAttribute(key))n.setAttribute(key,x(Number(n.getAttribute(key))));for(const key of ['y1','y2'])if(n.hasAttribute(key)){const value=Number(n.getAttribute(key));n.setAttribute(key,value>bottom?345+(value-bottom):y(value))}});
 svg.querySelectorAll('path').forEach(n=>{if(n.hasAttribute('d'))n.setAttribute('d',n.getAttribute('d').replace(/([ML])(-?[\d.]+),(-?[\d.]+)/g,(_,command,a,b)=>command+x(Number(a)).toFixed(2)+','+y(Number(b)).toFixed(2)));n.style.strokeWidth='1.8px'});
 svg.querySelectorAll('circle').forEach(n=>{n.setAttribute('cx',x(Number(n.getAttribute('cx'))));n.setAttribute('cy',y(Number(n.getAttribute('cy'))));n.setAttribute('r','3')});
 svg.querySelectorAll('text').forEach(n=>{const px=Number(n.getAttribute('x')),py=Number(n.getAttribute('y'));n.setAttribute('x',px<left?78:x(px));n.setAttribute('y',n.classList.contains('chart-axis-unit')?15:n.classList.contains('chart-timezone')?397:py>bottom?345+(py-bottom):y(py));n.style.fontSize='12px'});
 svg.setAttribute('viewBox','0 0 1152 400');
}
function chartImageSVG(card){
 const e=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
 const dark=document.body.classList.contains('dark'),bg=dark?'#15223a':'#ffffff',ink=dark?'#e5edfc':'#172b4d',muted=dark?'#a8b9d2':'#5d708c';let body='',height=600;
 const title=card.dataset.chartTitle||card.querySelector('h3,h2')?.textContent||'Market chart';
 const text=(x,y,value,size=14,color=ink,anchor='start',weight=400)=>`<text x="${x}" y="${y}" fill="${color}" font-family="Arial,sans-serif" font-size="${size}" font-weight="${weight}" text-anchor="${anchor}">${e(value)}</text>`;
 const svg=card.querySelector('svg.scatter,svg.overlay-chart,svg.annual-chart');
 if(svg?.classList.contains('scatter')){
  const rows=stocks.filter(s=>s.isin&&s.cap>0&&(scatterIndustry==='All industries'||s.sector===scatterIndustry)),g=scatterGeometry(rows,scatterMetric,1152,scatterScale),axis=v=>v===0?'0':amount(v,scatterMetric),label=scatterMetric==='earnings'?'Pretax profit · TTM':'Revenue · TTM';
  height=600;
  body='<g transform="translate(24 100)">'+text(g.left,16,'Market cap ('+currency+')',12,muted)+g.yTicks.map(v=>`<line x1="${g.left}" x2="1120" y1="${g.y(v)}" y2="${g.y(v)}" stroke="${dark?'#344358':'#dce0e5'}" stroke-width=".7"/>`+text(g.left-10,g.y(v)+4,axis(v),12,muted,'end')).join('')+g.xTicks.map(v=>`<line x1="${g.x(v)}" x2="${g.x(v)}" y1="${g.bottom}" y2="${g.bottom+5}" stroke="${muted}"/>`+text(g.x(v),g.bottom+23,axis(v),12,muted,'middle')).join('')+(Math.min(...g.points.map(s=>s[scatterMetric]))<0?`<line x1="${g.x(0)}" x2="${g.x(0)}" y1="${g.top}" y2="${g.bottom}" stroke="${muted}" stroke-dasharray="4 4"/>`:'')+g.points.map(s=>`<circle cx="${g.x(s[scatterMetric])}" cy="${g.y(s.cap)}" r="3.5" fill="${s[scatterMetric]<0?(dark?'#ff8290':'#c84157'):(dark?'#7aaeff':'#3979c5')}" opacity="${dark?.85:.7}"/>`).join('')+text(1120,g.height+4,label+' ('+currency+') · '+(scatterScale==='symlog'?'Log-like scale':'Linear scale'),12,muted,'end')+'</g>';
 }
 else if(svg){const clone=cloneChartForExport(svg);normalizeExportPriceChart(clone);clone.setAttribute('x','20');clone.setAttribute('y','95');clone.setAttribute('width','1160');const vb=clone.viewBox.baseVal;const h=1160*vb.height/vb.width;clone.setAttribute('height',h);body=new XMLSerializer().serializeToString(clone);height=h+180;const legend=[...card.querySelectorAll('.overlay-toggle[aria-pressed="true"]')];if(legend.length){height=h+175+Math.ceil(legend.length/2)*24;body+=legend.map((button,i)=>{const x=28+(i%2)*575,y=h+125+Math.floor(i/2)*24,swatch=button.querySelector('i'),style=getComputedStyle(swatch),color=style.borderTopColor||style.backgroundColor,dash=button.dataset.seriesDash||(style.borderTopStyle==='dotted'?'2 3':style.borderTopStyle==='dashed'?'6 3':'none'),name=button.querySelector('span')?.textContent||button.textContent,value=button.querySelector('b')?.textContent||'';return `<line x1="${x}" x2="${x+24}" y1="${y-4}" y2="${y-4}" stroke="${color}" stroke-width="2" stroke-dasharray="${dash}"/>`+text(x+32,y,name+' '+value,12)}).join('');}}
 else if(card.querySelector('.stock-treemap')){const map=card.querySelector('.stock-treemap'),r=map.getBoundingClientRect();height=650;const tiles=[...map.querySelectorAll('.treemap-tile')],byRank=new Map(tiles.map(t=>[Number(t.dataset.mapStock),t]));body=marketMapLayout(tiles.map(t=>({rank:Number(t.dataset.mapStock),cap:Number(t.dataset.mapCap)})),1152,480).map((item,index)=>{const tile=byRank.get(item.stock.rank),x=24+item.x,y=95+item.y,w=item.w,h=item.h;const color=tile.style.getPropertyValue('--tile-color')||getComputedStyle(tile).backgroundColor,font=Math.max(9,Math.min(26,parseFloat(getComputedStyle(tile.querySelector('.tile-symbol')).fontSize)*1.15));const sub=Math.max(9,font-5),block=font+2*sub+8,top=y+(h-block)/2;return `<defs><clipPath id="export-tile-${index}"><rect x="${x}" y="${y}" width="${w}" height="${h}"/></clipPath></defs><rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${color}" stroke="#d5dae1" stroke-width=".5"/><g clip-path="url(#export-tile-${index})">`+text(x+w/2,top+font,tile.querySelector('.tile-symbol').textContent,font,'#ffffff','middle')+text(x+w/2,top+font+sub+4,tile.querySelector('.tile-change').textContent,sub,'#ffffff','middle',650)+text(x+w/2,top+font+2*sub+8,tile.querySelector('.tile-cap').textContent,sub,'#ffffff','middle')+'</g>'}).join('');body+=text(24,605,'Area = market cap · Color = daily change · '+card.querySelector('#chart-sector')?.value,12,muted);}
 else if(card.querySelector('.chart-bar-list')){const bars=[...card.querySelectorAll('.interactive-bar')];height=150+bars.length*42;body=bars.map((bar,i)=>{const y=104+i*42,label=bar.querySelector('.bar-company>span:last-child').textContent,value=bar.querySelector('b').textContent,width=parseFloat(bar.querySelector('.bar-fill').style.width)/100*610;return text(24,y+16,label,13)+`<rect x="330" y="${y}" width="610" height="18" rx="3" fill="${dark?'#203755':'#edf3fc'}"/><rect x="330" y="${y}" width="${width}" height="18" rx="3" fill="#3d79ca"/>`+text(1168,y+16,value,13,ink,'end')}).join('');}
 else if(card.querySelector('.donut')){const entries=[...card.querySelectorAll('[data-chart-sector]')];let angle=-Math.PI/2;body=entries.map((entry,i)=>{const pct=Number(entry.dataset.share??parseFloat(entry.querySelector('b').textContent)),next=angle+pct/100*2*Math.PI,color=getComputedStyle(entry.querySelector('i')).backgroundColor;const x1=260+175*Math.cos(angle),y1=310+175*Math.sin(angle),x2=260+175*Math.cos(next),y2=310+175*Math.sin(next),path=`M260,310 L${x1},${y1} A175,175 0 ${pct>50?1:0},1 ${x2},${y2} Z`;angle=next;return `<path d="${path}" fill="${color}"/>`+`<rect x="545" y="${108+i*30}" width="10" height="10" rx="2" fill="${color}"/>`+text(567,118+i*30,entry.querySelector('span').textContent,13)+text(1130,118+i*30,pct.toFixed(1)+'%',13,ink,'end')}).join('')+`<circle cx="260" cy="310" r="125" fill="${bg}"/>`+text(260,310,entries.length,32,ink,'middle')+text(260,335,'sectors',13,muted,'middle');}
 else throw Error('No exportable chart data');
 const subtitle=svg?.classList.contains('annual-chart')?'Annual observations · Source '+(svg.dataset.sourceAsOf||'date unavailable')+' · 2026 YTD'+(currency==='INR'?' · Current display FX reference':''):card.id==='chart-sectors'?'Share of tracked market capitalization · grouped exchange sectors':card.id==='chart-scatter'?`${document.querySelector('#scatter-industry')?.selectedOptions[0]?.textContent} · ${card.querySelector('.coverage-chip')?.textContent}`:card.querySelector('.chart-summary')?.textContent||card.querySelector('p')?.textContent||'';
 return `<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="${height}" viewBox="0 0 1200 ${height}"><rect width="1200" height="${height}" fill="${bg}"/>${text(24,36,title,22)}${text(24,65,subtitle.slice(0,160),11,muted)}${body}${text(24,height-18,'IndiaStockView · '+(svg?.classList.contains('annual-chart')?'CompaniesMarketCap annual source':svg?.classList.contains('price-history-chart')?'Zerodha historical prices':'Quote and financial source periods vary')+' · Exported '+new Date().toLocaleString('en-GB',{timeZone:'Asia/Kolkata',day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'})+' IST',10,muted)}</svg>`;
}
async function downloadChartImage(card,type,button){if(card.querySelector('.kite-history-content[aria-busy="true"]')){toast('The selected timeline is still loading.');return}const previousText=button.textContent;button.disabled=true;button.setAttribute('aria-busy','true');button.textContent='Preparing…';try{const source=chartImageSVG(card),blob=new Blob([source],{type:'image/svg+xml;charset=utf-8'});let output=blob;if(type==='png'){const img=new Image(),url=URL.createObjectURL(blob);let imageTimer;try{await new Promise((resolve,reject)=>{imageTimer=setTimeout(()=>reject(Error('Image conversion timed out')),15000);img.onload=()=>{clearTimeout(imageTimer);resolve()};img.onerror=()=>{clearTimeout(imageTimer);reject(Error('Image conversion failed'))};img.src=url});const canvas=document.createElement('canvas');canvas.width=img.naturalWidth*2;canvas.height=img.naturalHeight*2;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);output=await new Promise(resolve=>canvas.toBlob(resolve,'image/png'));if(!output)throw Error('PNG conversion failed')}finally{clearTimeout(imageTimer);img.onload=null;img.onerror=null;URL.revokeObjectURL(url)}}const a=document.createElement('a'),url=URL.createObjectURL(output);a.href=url;a.download='india-stock-view-'+(card.dataset.chartTitle||card.querySelector('h3,h2')?.textContent||'chart').toLowerCase().replace(/[^a-z0-9]+/g,'-')+'.'+type;try{a.click()}finally{setTimeout(()=>URL.revokeObjectURL(url),1000);}toast('Chart downloaded as '+type.toUpperCase())}catch{toast(type==='png'?'Could not create PNG. Please try SVG.':'Could not export this chart. Please try again.')}finally{button.disabled=false;button.removeAttribute('aria-busy');button.textContent=previousText}}
function installChartDownloads(){document.querySelectorAll('.charts-workspace>.card,.compare-overlay,.stock-chart-card').forEach(card=>{if(card.querySelector(':scope>.chart-image-actions')||!card.querySelector('svg,.stock-treemap,.chart-bar-list,.donut'))return;const actions=document.createElement('div');actions.className='chart-image-actions';actions.setAttribute('role','group');actions.setAttribute('aria-label','Download chart image');for(const type of ['png','svg']){const button=document.createElement('button');button.textContent='↓ '+type.toUpperCase();button.title='Download chart as '+type.toUpperCase();button.setAttribute('aria-label',button.title);button.onclick=()=>downloadChartImage(card,type,button);actions.append(button)}card.append(actions)})}
installChartDownloads();
let chartDownloadFrame=0;
new MutationObserver(records=>{
 // Quote text and hover movement do not change the set of downloadable charts.
 const chart='svg,.stock-treemap,.chart-bar-list,.donut';
 if(chartDownloadFrame||!records.some(record=>[...record.addedNodes].some(node=>node.nodeType===1&&(node.matches(chart)||node.querySelector(chart)))))return;
 chartDownloadFrame=requestAnimationFrame(()=>{chartDownloadFrame=0;installChartDownloads()});
}).observe(document.querySelector('#content'),{childList:true,subtree:true});
